#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_iChannel0(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_iChannel0(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_zoom;
uniform float amzp_rotation;

        float2x2 Rot(float a) {
            float s = sin(a), c = cos(a);
            return float2x2(c, -s, s, c);
        }
        float sdBox(float3 p, float3 b) {
            float3 q = abs(p) - b;
            return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
        }
        float2 map(float3 p) {
            float2 res = float2(50.0, 0.0);
            float dFloor = p.y;
            float dWall = 2.5 - p.z;
            if(dFloor < res.x) res = float2(dFloor, 1.0);
            if(dWall < res.x) res = float2(dWall, 5.0);
            float tH = 0.8;
            float tW = 1.4;
            float tD = 0.7;
            float tThick = 0.05;
            float3 pTop = p - float3(0.0, tH, 0.0);
            float dTop = sdBox(pTop, float3(tW*0.5, tThick*0.5, tD*0.5));
            float3 pLegs = p;
            pLegs.x = abs(pLegs.x);
            pLegs.z = abs(pLegs.z);
            pLegs -= float3(tW*0.4, tH*0.5, tD*0.4);
            float dLegs = sdBox(pLegs, float3(0.04, tH*0.5, 0.04));
            float dTable = min(dTop, dLegs);
            if(dTable < res.x) res = float2(dTable, 2.0);
            float3 pm = p - float3(0.0, tH + tThick*0.5, 0.0);
            float dBase = sdBox(pm - float3(0.0, 0.01, 0.0), float3(0.15, 0.01, 0.12));
            float dNeck = sdBox(pm - float3(0.0, 0.15, 0.05), float3(0.04, 0.15, 0.02));
            float3 ph = pm - float3(0.0, 0.45, 0.0);
            float dBezel = sdBox(ph, float3(0.6, 0.35, 0.04));
            float dMonitorFrame = min(dBase, min(dNeck, dBezel));
            if(dMonitorFrame < res.x) res = float2(dMonitorFrame, 3.0);
            float dScreen = sdBox(ph - float3(0.0, 0.0, -0.041), float3(0.57, 0.32, 0.001));
            if(dScreen < res.x) res = float2(dScreen, 4.0);
            return res;
        }
        float2 rayMarch(float3 ro, float3 rd) {
            float dO = 0.0;
            float m = 0.0;
            for(int i=0; i<100; i++) {
                float3 p = ro + rd * dO;
                float2 dS = map(p);
                dO += dS.x;
                m = dS.y;
                if(dO > 50.0 || abs(dS.x) < 0.001) break;
            }
            return float2(dO, m);
        }
        float3 getNormal(float3 p) {
            float d = map(p).x;
            float2 e = float2(0.001, 0);
            float3 n = d - float3(
                map(p-e.xyy).x,
                map(p-e.yxy).x,
                map(p-e.yyx).x);
            return normalize(n);
        }
        float getShadow(float3 p, float3 l, float k) {
            float res = 1.0;
            float t = 0.02;
            for(int i=0; i<20; i++) {
                float h = map(p + l * t).x;
                if(h < 0.001) return 0.0;
                res = min(res, k*h/t);
                t += h;
                if(t > 10.0) break;
            }
            return res;
        }
        void amzRender() {
            float2 uv = amzScreenNorm() - 0.5;
            uv.x *= (layer.x / layer.y);
            float d = 4.0 / amzp_zoom;
            float3 pivot = float3(0.0, 1.25, 0.0);
            float3 camPos = float3(0.0, 0.5, -d);
            camPos.xz *= Rot(amzp_rotation);
            camPos += pivot;
            float3 lookAt = pivot;
            float3 f = normalize(lookAt - camPos);
            float3 r = normalize(cross(float3(0,1,0), f));
            float3 u = cross(f, r);
            float3 rd = normalize(f + uv.x * r + uv.y * u);
            float2 tr = rayMarch(camPos, rd);
            float dist = tr.x;
            float m = tr.y;
            float3 col = float3(0.05, 0.05, 0.08);
            if(dist < 50.0) {
                float3 p = camPos + rd * dist;
                float3 n = getNormal(p);
                float3 lightPos = float3(2.0, 4.0, -2.0);
                float3 l = normalize(lightPos - p);
                float shadow = getShadow(p, l, 8.0);
                float diff = max(0.0, dot(n, l));
                float amb = 0.05;
                float3 albedo = float3(0.5);
                if(m == 1.0) {
                    albedo = float3(0.15);
                    if((fract(p.x) > 0.5) != (fract(p.z) > 0.5)) albedo *= 0.8;
                } else if(m == 2.0) {
                    albedo = float3(0.95);
                } else if(m == 3.0) {
                    albedo = float3(0.1);
                } else if(m == 5.0) {
                    albedo = float3(0.8, 0.8, 0.85);
                } else if(m == 4.0) {
                    float3 screenCenter = float3(0.0, 1.275, -0.041);
                    float3 local = p - screenCenter;
                    float2 sUV = local.xy / float2(0.57, 0.32) * 0.5 + 0.5;
                    sUV = clamp(sUV, 0.0, 1.0);
                    albedo = amzTexture(0, sUV).rgb;
                    col = albedo * 1.5;
                }
                if(m != 4.0) {
                    col = albedo * (diff * shadow + amb);
                    float3 h = normalize(l - rd);
                    float spec = pow(max(0.0, dot(n, h)), 32.0);
                    float specStr = (m == 2.0) ? 0.5 : 0.3;
                    col += float3(spec * specStr * shadow);
                }
                col = mix(col, float3(0.05, 0.05, 0.08), 1.0 - exp(-dist * 0.02));
            }
            col = pow(col, float3(0.4545));
            amzOutput = float4(col, 1.0);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

